param(
    [Parameter(Mandatory = $false)]
    [string]$ProjectRoot = ".",

    [Parameter(Mandatory = $false)]
    [switch]$RestoreLatest
)

$ErrorActionPreference = "Stop"

function Resolve-ProjectRoot([string]$InputPath) {
    $resolved = (Resolve-Path -LiteralPath $InputPath).Path

    if (Test-Path (Join-Path $resolved "src\main\webapp")) {
        return $resolved
    }

    $children = @(
        Get-ChildItem -LiteralPath $resolved -Directory |
        Where-Object { Test-Path (Join-Path $_.FullName "src\main\webapp") }
    )

    if ($children.Count -eq 1) {
        return $children[0].FullName
    }

    throw "Không tìm thấy project có thư mục src\main\webapp tại: $resolved"
}

$ProjectRoot = Resolve-ProjectRoot $ProjectRoot
$ProjectName = Split-Path $ProjectRoot -Leaf
$BackupBase = Join-Path (Split-Path $ProjectRoot -Parent) ($ProjectName + "_format_backups")

if ($RestoreLatest) {
    if (-not (Test-Path $BackupBase)) {
        throw "Không tìm thấy thư mục backup: $BackupBase"
    }

    $latest = Get-ChildItem -LiteralPath $BackupBase -Directory |
        Sort-Object Name -Descending |
        Select-Object -First 1

    if ($null -eq $latest) {
        throw "Không có bản backup nào trong: $BackupBase"
    }

    Write-Host "Đang khôi phục từ: $($latest.FullName)" -ForegroundColor Cyan

    Get-ChildItem -LiteralPath $latest.FullName -Recurse -File | ForEach-Object {
        $relative = $_.FullName.Substring($latest.FullName.Length).TrimStart("\", "/")
        $destination = Join-Path $ProjectRoot $relative
        $destinationDir = Split-Path $destination -Parent

        New-Item -ItemType Directory -Force -Path $destinationDir | Out-Null
        Copy-Item -LiteralPath $_.FullName -Destination $destination -Force
        Write-Host "  RESTORE  $relative" -ForegroundColor Green
    }

    Write-Host "Khôi phục hoàn tất." -ForegroundColor Green
    exit 0
}

$payloadBase64 = @'

'@

Add-Type -AssemblyName System.IO.Compression.FileSystem

$tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("nestora_format_" + [Guid]::NewGuid().ToString("N"))
$tempZip = Join-Path $tempRoot "payload.zip"
$tempExtract = Join-Path $tempRoot "payload"

New-Item -ItemType Directory -Force -Path $tempRoot | Out-Null
New-Item -ItemType Directory -Force -Path $tempExtract | Out-Null

try {
    [System.IO.File]::WriteAllBytes($tempZip, [Convert]::FromBase64String($payloadBase64))
    [System.IO.Compression.ZipFile]::ExtractToDirectory($tempZip, $tempExtract)

    $files = @(Get-ChildItem -LiteralPath $tempExtract -Recurse -File)

    if ($files.Count -eq 0) {
        throw "Payload format trống."
    }

    $timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
    $backupDir = Join-Path $BackupBase $timestamp
    New-Item -ItemType Directory -Force -Path $backupDir | Out-Null

    Write-Host "Project: $ProjectRoot" -ForegroundColor Cyan
    Write-Host "Backup:  $backupDir" -ForegroundColor Cyan
    Write-Host "Đang backup source hiện tại..." -ForegroundColor Cyan

    foreach ($file in $files) {
        $relative = $file.FullName.Substring($tempExtract.Length).TrimStart("\", "/")
        $target = Join-Path $ProjectRoot $relative

        if (Test-Path $target) {
            $backupFile = Join-Path $backupDir $relative
            $backupParent = Split-Path $backupFile -Parent
            New-Item -ItemType Directory -Force -Path $backupParent | Out-Null
            Copy-Item -LiteralPath $target -Destination $backupFile -Force
        }
    }

    Write-Host "Đang format code và sửa icon menu thu gọn..." -ForegroundColor Cyan

    foreach ($file in $files) {
        $relative = $file.FullName.Substring($tempExtract.Length).TrimStart("\", "/")
        $target = Join-Path $ProjectRoot $relative
        $targetParent = Split-Path $target -Parent

        New-Item -ItemType Directory -Force -Path $targetParent | Out-Null
        Copy-Item -LiteralPath $file.FullName -Destination $target -Force
        Write-Host "  UPDATE   $relative" -ForegroundColor Green
    }

    Write-Host ""
    Write-Host "HOÀN TẤT" -ForegroundColor Green
    Write-Host "- Đã format lại JSP, JSPF, CSS, JavaScript, XML và Java đang bị dồn dòng." -ForegroundColor White
    Write-Host "- Không sửa Servlet, DAO, Model, URL, dữ liệu hoặc logic nghiệp vụ." -ForegroundColor White
    Write-Host "- Đã sửa icon SVG biến mất khi thu gọn sidebar." -ForegroundColor White
    Write-Host "- Icon đã chuyển sang thẻ <i>; chữ menu vẫn là <span> nên không bị ẩn nhầm." -ForegroundColor White
    Write-Host ""
    Write-Host "Tiếp theo trong Eclipse:" -ForegroundColor Yellow
    Write-Host "1. Project > Refresh" -ForegroundColor Yellow
    Write-Host "2. Project > Clean" -ForegroundColor Yellow
    Write-Host "3. Tomcat > Clean, Publish và restart" -ForegroundColor Yellow
    Write-Host "4. Chrome > Ctrl + F5" -ForegroundColor Yellow
}
finally {
    if (Test-Path $tempRoot) {
        Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
    }
}
